import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
// Run the function under timezones with daylight saving
function run(tz, a, b) {
  const code = `import('${new URL('../dates.js', import.meta.url).href}').then(m => console.log(JSON.stringify(m.daysBetween('${a}', '${b}'))))`;
  return JSON.parse(execFileSync(process.execPath, ['-e', code], { env: { ...process.env, TZ: tz } }).toString());
}
for (const tz of ['Australia/Sydney', 'America/New_York', 'UTC']) {
  test(`autumn change ${tz}`, () => assert.deepEqual(run(tz, '2026-04-04', '2026-04-06'), ['2026-04-04', '2026-04-05', '2026-04-06']));
  test(`spring change ${tz}`, () => assert.deepEqual(run(tz, '2026-03-07', '2026-03-09'), ['2026-03-07', '2026-03-08', '2026-03-09']));
  test(`october ${tz}`, () => assert.equal(run(tz, '2026-09-30', '2026-10-06').length, 7));
  test(`same day ${tz}`, () => assert.deepEqual(run(tz, '2026-01-01', '2026-01-01'), ['2026-01-01']));
}

